import heapq

def match(orders):
    buy_heap = []   # entries: (-price, time, id)  max-price, then earliest time
    sell_heap = []  # entries: (price, time, id)   min-price, then earliest time
    book = {}       # id -> dict(side, price, qty, time, active)
    trades = []

    time_counter = 0

    for order in orders:
        time_counter += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                s_price, s_time, s_id = sell_heap[0]
                info = book.get(s_id)
                if not info or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and s_price > price:
                    break
                heapq.heappop(sell_heap)
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, s_id, s_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] > 0:
                    heapq.heappush(sell_heap, (s_price, s_time, s_id))
                else:
                    info['active'] = False

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining,
                             'time': time_counter, 'active': True}
                heapq.heappush(buy_heap, (-price, time_counter, oid))
            # ioc/market: remainder discarded

        else:  # side == 'sell'
            while remaining > 0 and buy_heap:
                neg_price, b_time, b_id = buy_heap[0]
                info = book.get(b_id)
                if not info or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                b_price = -neg_price
                if typ != 'market' and b_price < price:
                    break
                heapq.heappop(buy_heap)
                trade_qty = min(remaining, info['qty'])
                trades.append([b_id, oid, b_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] > 0:
                    heapq.heappush(buy_heap, (neg_price, b_time, b_id))
                else:
                    info['active'] = False

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining,
                             'time': time_counter, 'active': True}
                heapq.heappush(sell_heap, (price, time_counter, oid))
            # ioc/market: remainder discarded

    return trades

